import React, { useState, useEffect, useCallback } from 'react';
import { 
  Users, Calendar, ClipboardCheck, LayoutDashboard, Settings, LogOut, Menu, Trophy, RefreshCw, Loader2,
  Activity, HeartPulse, QrCode, PenTool, Sparkles, Package, Printer
} from 'lucide-react';
import { createClient } from '@supabase/supabase-js';
import { AppUser, AppState, Person } from './types';
import html2pdf from 'html2pdf.js';

// Components
import Dashboard from './components/Dashboard';
import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import MatchPlanner from './components/MatchPlanner';
import SettingsView from './components/SettingsView';
import PlayerReport from './components/PlayerReport';
import WarehouseManagement from './components/WarehouseManagement';
import Login from './components/Login';
import ClubLogo from './components/ClubLogo';
import AIAssistant from './components/AIAssistant';
import ChatBot from './components/ChatBot';
import TechnicalReports from './components/TechnicalReports';
import TacticalBoard from './components/TacticalBoard';
import MedicalCenter from './components/MedicalCenter';
import QRManager from './components/QRManager';
import VisualAnalytics from './components/VisualAnalytics';

export const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

export const supabase = createClient(
  'https://kfwqoigsghlgigjriyxf.supabase.co',
  'sb_publishable_O2vR2yKUG-FVeaydD4z6Lg_tjFcKDic'
);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'error' | 'syncing'>('synced');
  const [isInitialLoading, setIsInitialLoading] = useState(false);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_secure_v11');
    if (saved) { try { return JSON.parse(saved); } catch (e) { return {} as AppState; } }
    return {
      currentUser: null, categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [], sessions: [], matches: [], warehouse: [], technicalReports: [],
      attendance: [], users: [], notifications: [], globalCategoryFilter: 'الكل',
      injuries: [], tacticalPlans: []
    };
  });

  const fetchAllData = useCallback(async (user: AppUser) => {
    setIsInitialLoading(true);
    setSyncStatus('syncing');
    try {
      const [ppl, mtch, attn, wrhs, tech, usrs, sess, cats, inj, tact] = await Promise.all([
        supabase.from('people').select('*'),
        supabase.from('matches').select('*'),
        supabase.from('attendance').select('*'),
        supabase.from('warehouse').select('*'),
        supabase.from('technical_reports').select('*'),
        supabase.from('app_users').select('*'),
        supabase.from('sessions').select('*'),
        supabase.from('categories').select('*'),
        supabase.from('injuries').select('*'),
        supabase.from('tactical_plans').select('*')
      ]);

      setState(prev => ({
        ...prev,
        currentUser: user,
        people: ppl.data || [],
        matches: mtch.data || [],
        attendance: attn.data || [],
        warehouse: wrhs.data || [],
        technicalReports: tech.data || [],
        users: usrs.data || [],
        sessions: sess.data || [],
        categories: cats.data && cats.data.length > 0 ? cats.data.map(c => c.name) : prev.categories,
        injuries: inj.data || [],
        tacticalPlans: tact.data || []
      }));
      setSyncStatus('synced');
    } catch (e) {
      console.error("Fetch Error:", e);
      setSyncStatus('error');
    } finally {
      setIsInitialLoading(false);
    }
  }, []);

  const updateStateAndSync = useCallback((updater: (prev: AppState) => AppState) => {
    setState(prev => {
      const nextState = updater(prev);
      localStorage.setItem('alkarama_secure_v11', JSON.stringify(nextState));

      if (nextState.currentUser) {
        setSyncStatus('syncing');
        // Trigger background sync
        (async () => {
          try {
            await Promise.all([
              supabase.from('people').upsert(nextState.people),
              supabase.from('matches').upsert(nextState.matches),
              supabase.from('attendance').upsert(nextState.attendance),
              supabase.from('warehouse').upsert(nextState.warehouse),
              supabase.from('technical_reports').upsert(nextState.technicalReports),
              supabase.from('app_users').upsert(nextState.users),
              supabase.from('sessions').upsert(nextState.sessions),
              supabase.from('injuries').upsert(nextState.injuries),
              supabase.from('tactical_plans').upsert(nextState.tacticalPlans),
              supabase.from('categories').upsert(nextState.categories.map(name => ({ name })), { onConflict: 'name' })
            ]);
            setSyncStatus('synced');
          } catch (e) {
            console.error("Sync Error:", e);
            setSyncStatus('error');
          }
        })();
      }
      return nextState;
    });
  }, []);

  const onLoginAttempt = async (u: string, p: string) => {
    if ((u === 'عزت' || u.toUpperCase() === 'IZZAT') && p === '123') {
      const user: AppUser = { id: 'root', username: 'عزت عامر الشيخة', role: 'مدير' };
      await fetchAllData(user);
      return user;
    }
    const { data, error } = await supabase.from('app_users').select('*').eq('username', u).eq('password', p).maybeSingle();
    if (error) throw new Error("فشل الاتصال بالخادم");
    if (!data) return null;
    await fetchAllData(data);
    return data;
  };

  if (!state.currentUser) return <Login onLoginAttempt={onLoginAttempt} />;

  if (isInitialLoading) return (
    <div className="min-h-screen bg-[#020617] flex flex-col items-center justify-center p-6 text-[#f8fafc] font-['IBM_Plex_Sans_Arabic']">
       <div className="relative">
          <ClubLogo size={140} className="animate-pulse mb-8" />
          <Loader2 className="absolute inset-0 animate-spin text-orange-500 m-auto" size={160} strokeWidth={1} />
       </div>
       <h2 className="text-xl font-bold tracking-tight">جاري المزامنة...</h2>
    </div>
  );

  const navItems = [
    { id: 'dashboard', label: 'الرئيسية', icon: LayoutDashboard },
    { id: 'squad', label: 'الفريق', icon: Users },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'attendance', label: 'الحضور', icon: ClipboardCheck },
    { id: 'tactics', label: 'التكتيك', icon: PenTool },
    { id: 'medical', label: 'الطبابة', icon: HeartPulse },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'warehouse', label: 'المستودع', icon: Package },
    { id: 'qr', label: 'نظام QR', icon: QrCode },
    { id: 'analytics', label: 'التحليلات', icon: Activity },
    { id: 'ai', label: 'الذكاء الفني', icon: Sparkles },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  return (
    <div className="flex h-screen bg-[#020617] text-[#f8fafc] font-['IBM_Plex_Sans_Arabic'] overflow-hidden" dir="rtl">
      <aside className={`${isSidebarOpen ? 'w-72' : 'w-24'} bg-[#0f172a] border-l border-white/5 transition-all duration-300 flex flex-col z-50 shadow-2xl relative`}>
        <div className="p-8 flex items-center justify-center gap-4">
           <ClubLogo size={isSidebarOpen ? 50 : 35} />
           {isSidebarOpen && <span className="text-lg font-bold text-white tracking-tight">الكرامة SC</span>}
        </div>

        <nav className="flex-1 px-4 space-y-1 overflow-y-auto custom-scrollbar">
          {navItems.map(item => (
            <button key={item.id} onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 group
              ${activeTab === item.id ? 'bg-orange-500 text-white shadow-lg shadow-orange-500/20' : 'hover:bg-white/5 text-slate-400 hover:text-white'}`}>
              <item.icon size={20} className={activeTab === item.id ? 'text-white' : 'group-hover:text-orange-500'} />
              {isSidebarOpen && <span className="text-sm font-medium">{item.label}</span>}
              {activeTab === item.id && isSidebarOpen && <div className="mr-auto w-1.5 h-1.5 bg-white rounded-full"></div>}
            </button>
          ))}
        </nav>

        <div className="p-4 mt-auto">
          <button onClick={() => setState(prev => ({ ...prev, currentUser: null }))} 
            className="w-full p-3 rounded-xl text-red-400 bg-red-500/5 hover:bg-red-500/10 border border-red-500/20 transition-all flex items-center justify-center gap-3">
            <LogOut size={18} /> {isSidebarOpen && <span className="text-sm font-semibold">تسجيل الخروج</span>}
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col min-w-0">
        <header className="h-20 bg-[#0f172a]/60 backdrop-blur-md border-b border-white/5 px-8 flex items-center justify-between z-40">
          <div className="flex items-center gap-6">
             <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="p-2.5 bg-white/5 rounded-xl hover:bg-orange-500 hover:text-white transition-all">
                <Menu size={20} />
             </button>
             <h1 className="text-xl font-bold tracking-tight">{navItems.find(n => n.id === activeTab)?.label}</h1>
          </div>

          <div className="flex items-center gap-4">
             <div className="flex items-center gap-2 px-4 py-2 bg-white/5 rounded-full border border-white/5">
                <div className={`w-2 h-2 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500 animate-pulse' : 'bg-orange-500 animate-spin'}`}></div>
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{syncStatus}</span>
             </div>
             <button onClick={() => html2pdf().from(document.getElementById('report-section')).save()} 
                className="bg-white text-slate-900 px-6 py-2.5 rounded-xl font-bold text-xs hover:bg-orange-500 hover:text-white transition-all shadow-xl shadow-black/20 flex items-center gap-2">
                <Printer size={16} /> تصدير PDF
             </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
          <div id="report-section" className="max-w-6xl mx-auto space-y-8 fade-up">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={updateStateAndSync} onMatchClick={(id) => { setSelectedMatchId(id); setActiveTab('matches'); }} onSessionClick={() => setActiveTab('attendance')} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={updateStateAndSync} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={() => {}} getSuspension={() => ({isSuspended:false,currentYellows:0,hasActiveRed:false})} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={updateStateAndSync} addLog={() => {}} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={updateStateAndSync} addLog={() => {}} />}
            {activeTab === 'tactics' && <TacticalBoard state={state} setState={updateStateAndSync} />}
            {activeTab === 'medical' && <MedicalCenter state={state} setState={updateStateAndSync} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={updateStateAndSync} defaultSelectedId={selectedMatchId} getSuspension={() => ({isSuspended:false,currentYellows:0,hasActiveRed:false})} />}
            {activeTab === 'warehouse' && <WarehouseManagement state={state} setState={updateStateAndSync} addLog={() => {}} />}
            {activeTab === 'qr' && <QRManager state={state} setState={updateStateAndSync} />}
            {activeTab === 'analytics' && <VisualAnalytics state={state} />}
            {activeTab === 'ai' && <AIAssistant state={state} />}
            {activeTab === 'settings' && <SettingsView state={state} setState={updateStateAndSync} addLog={() => {}} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </div>
      </div>

      <ChatBot state={state} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  UserPlus, Trash2, Search, Edit2, MapPin, Calendar, ChevronRight, 
  X, Save, Target
} from 'lucide-react';
import { AppState, Person, Category, Role } from '../types';
import { generateUUID } from '../App';

interface SquadManagementProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  onOpenReport?: (player: Person) => void;
  addLog?: (m: string, d?: string, t?: any) => void;
  getSuspension?: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport, addLog }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [localCategoryFilter, setLocalCategoryFilter] = useState('الكل');
  const [activeSubTab, setActiveSubTab] = useState<'players' | 'staff'>('players');

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: state.globalCategoryFilter === 'الكل' ? (state.categories[0] || 'الرجال') : state.globalCategoryFilter,
    joinDate: new Date().toISOString().split('T')[0]
  });

  const members = state.people.filter(p => {
    const matchCat = localCategoryFilter === 'الكل' || p.category === localCategoryFilter;
    const matchSearch = p.name.includes(searchTerm);
    return matchCat && matchSearch && (activeSubTab === 'players' ? p.role === 'لاعب' : p.role !== 'لاعب');
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.category) return alert('يرجى إدخال الاسم والفئة على الأقل');

    setState(prev => {
      if (editingId) {
        const updatedPeople = prev.people.map(p => p.id === editingId ? { ...p, ...formData } as Person : p);
        addLog?.('تعديل عضو', `تم تحديث بيانات: ${formData.name}`, 'info');
        return { ...prev, people: updatedPeople };
      } else {
        const newPerson: Person = {
          id: generateUUID(),
          name: formData.name!,
          fatherName: formData.fatherName || '',
          motherName: formData.motherName || '',
          birthDate: formData.birthDate || '',
          birthPlace: formData.birthPlace || '',
          khana: formData.khana || '',
          nationalId: formData.nationalId || '',
          federalNumber: formData.federalNumber || '',
          internationalId: formData.internationalId || '',
          address: formData.address || '',
          category: formData.category as Category,
          role: formData.role as Role,
          number: formData.number,
          phone: formData.phone,
          joinDate: formData.joinDate || new Date().toISOString().split('T')[0],
          height: formData.height,
          weight: formData.weight,
          position: formData.position,
          notes: formData.notes
        };
        addLog?.('إضافة عضو', `تمت إضافة ${newPerson.name} إلى الفريق`, 'success');
        return { ...prev, people: [newPerson, ...prev.people] };
      }
    });

    setIsModalOpen(false);
    setEditingId(null);
    setFormData({ 
      role: 'لاعب',
      category: state.globalCategoryFilter === 'الكل' ? (state.categories[0] || 'الرجال') : state.globalCategoryFilter,
      joinDate: new Date().toISOString().split('T')[0]
    });
  };

  const handleDelete = (id: string, name: string) => {
    if (confirm(`هل أنت متأكد من حذف ${name} نهائياً؟`)) {
      setState(prev => ({ ...prev, people: prev.people.filter(p => p.id !== id) }));
      addLog?.('حذف عضو', `تمت إزالة ${name} من السجلات`, 'error');
    }
  };

  const openEdit = (person: Person) => {
    setEditingId(person.id);
    setFormData(person);
    setIsModalOpen(true);
  };

  const inputClass = "w-full bg-slate-900 border border-white/10 rounded-xl py-3 px-4 text-white font-medium focus:border-orange-500 outline-none transition-all";
  const labelClass = "text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 block mr-1";

  return (
    <div className="space-y-10">
      <div className="modern-card p-6 flex flex-col md:flex-row gap-6 items-center border-white/5">
         <div className="flex-1 relative w-full group">
            <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-orange-500 transition-colors" size={20} />
            <input type="text" placeholder="البحث عن اسم لاعب أو كادر..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)}
              className="w-full bg-slate-900/50 border border-white/5 rounded-2xl py-4 pr-14 pl-6 text-white outline-none focus:bg-[#0f172a] transition-all" />
         </div>
         <select value={localCategoryFilter} onChange={e => setLocalCategoryFilter(e.target.value)}
            className="w-full md:w-64 bg-slate-900/50 border border-white/5 rounded-2xl p-4 font-bold text-white outline-none cursor-pointer hover:bg-white/5 transition-all">
            <option value="الكل">جميع الفئات</option>
            {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
         </select>
         <button 
           onClick={() => { 
             setEditingId(null); 
             setFormData({ 
               role: 'لاعب', 
               category: state.globalCategoryFilter === 'الكل' ? (state.categories[0] || 'الرجال') : state.globalCategoryFilter,
               joinDate: new Date().toISOString().split('T')[0]
             }); 
             setIsModalOpen(true); 
           }}
           className="bg-orange-500 text-white px-8 py-4 rounded-2xl font-bold text-sm flex items-center gap-3 shadow-xl shadow-orange-500/10 hover:bg-orange-600 transition-all active:scale-95 whitespace-nowrap"
         >
            <UserPlus size={20}/> إضافة عضو
         </button>
      </div>

      <div className="flex p-1.5 bg-slate-900/80 backdrop-blur border border-white/5 rounded-2xl w-fit mx-auto md:mx-0">
          <button onClick={() => setActiveSubTab('players')}
            className={`px-10 py-3 rounded-xl font-bold text-xs transition-all ${activeSubTab === 'players' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-400 hover:bg-white/5'}`}>
            اللاعبين
          </button>
          <button onClick={() => setActiveSubTab('staff')}
            className={`px-10 py-3 rounded-xl font-bold text-xs transition-all ${activeSubTab === 'staff' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-400 hover:bg-white/5'}`}>
            الكوادر
          </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {members.map(person => (
          <div key={person.id} className="modern-card p-8 group hover:border-orange-500/30 transition-all duration-300 flex flex-col">
             <div className="flex justify-between items-start mb-8">
                <div className="relative">
                   <div className="w-16 h-16 bg-slate-800 rounded-2xl flex items-center justify-center font-bold text-3xl text-white border border-white/5 overflow-hidden group-hover:bg-slate-700 transition-all">
                      {person.name.charAt(0)}
                   </div>
                   {person.role === 'لاعب' && (
                     <div className="absolute -top-3 -left-3 w-8 h-8 bg-orange-500 text-white rounded-lg flex items-center justify-center font-bold text-xs border-2 border-[#0f172a] shadow-xl">
                        {person.number || '0'}
                     </div>
                   )}
                </div>
                <div className="flex flex-col items-end">
                   <span className="text-[9px] font-bold text-orange-500 uppercase tracking-[0.2em] mb-1">{person.category}</span>
                   <span className="text-xs font-semibold text-slate-400">{person.role}</span>
                </div>
             </div>

             <h3 className="text-xl font-bold text-white mb-4 tracking-tight">{person.name}</h3>

             <div className="space-y-3 mb-8">
                <div className="flex items-center gap-3 text-slate-500 text-[10px] font-bold uppercase tracking-widest">
                   <MapPin size={12}/> {person.birthPlace || '---'}
                </div>
                <div className="flex items-center gap-3 text-slate-500 text-[10px] font-bold uppercase tracking-widest">
                   <Calendar size={12}/> {person.birthDate || '---'}
                </div>
                {person.position && (
                  <div className="flex items-center gap-3 text-orange-500/70 text-[10px] font-bold uppercase tracking-widest">
                    <Target size={12}/> {person.position}
                  </div>
                )}
             </div>

             <div className="mt-auto pt-6 border-t border-white/5 flex justify-between items-center">
                <button onClick={() => onOpenReport?.(person)} className="text-xs font-bold text-white/50 hover:text-orange-500 transition-all flex items-center gap-2">
                   الملف الفني <ChevronRight size={14}/>
                </button>
                <div className="flex gap-2">
                   <button onClick={() => openEdit(person)} className="p-2.5 bg-white/5 rounded-xl text-slate-400 hover:bg-white/10 hover:text-white transition-all"><Edit2 size={16}/></button>
                   <button onClick={() => handleDelete(person.id, person.name)} className="p-2.5 bg-white/5 rounded-xl text-slate-400 hover:bg-red-500/20 hover:text-red-500 transition-all"><Trash2 size={16}/></button>
                </div>
             </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
           <div className="bg-[#0f172a] border border-white/10 rounded-[2.5rem] w-full max-w-2xl max-h-[90vh] overflow-y-auto custom-scrollbar shadow-2xl animate-in zoom-in-95 duration-300">
              <div className="sticky top-0 bg-[#0f172a] p-8 border-b border-white/5 flex justify-between items-center z-10">
                 <h3 className="text-2xl font-bold text-white flex items-center gap-4">
                    <UserPlus className="text-orange-500" /> {editingId ? 'تعديل بيانات العضو' : 'إضافة عضو جديد للفريق'}
                 </h3>
                 <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/5 rounded-full transition-all text-slate-400 hover:text-white">
                    <X size={24}/>
                 </button>
              </div>

              <form onSubmit={handleSave} className="p-10 space-y-8">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-1">
                       <label className={labelClass}>الاسم الكامل</label>
                       <input required className={inputClass} value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} placeholder="مثال: أحمد محمد علي" />
                    </div>
                    <div className="space-y-1">
                       <label className={labelClass}>الصفة / الدور</label>
                       <select className={inputClass} value={formData.role} onChange={e => setFormData({...formData, role: e.target.value as any})}>
                          <option value="لاعب">لاعب</option>
                          <option value="مدرب">مدرب</option>
                          <option value="مساعد مدرب">مساعد مدرب</option>
                          <option value="مدرب حراس">مدرب حراس</option>
                          <option value="إداري">إداري</option>
                          <option value="طبيب">طبيب</option>
                       </select>
                    </div>
                    <div className="space-y-1">
                       <label className={labelClass}>الفئة</label>
                       <select className={inputClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
