          <Printer size={20} /> طباعة السجل الكامل
        </button>
      </div>

      {/* Header Card */}
      <div className="bg-white rounded-[4rem] overflow-hidden relative border-4 border-slate-900 shadow-[15px_15px_0px_0px_rgba(0,31,63,1)]">
