interface PlayerReportProps {
  state: AppState;
  // Fix: Added setState to props to enable updating global state
  setState: (updater: (prev: AppState) => AppState) => void;
  player: Person | null;
  onBack: () => void;
}

const PlayerReport: React.FC<PlayerReportProps> = ({ state, setState, player, onBack }) => {
  const [isSavingReport, setIsSavingReport] = useState(false);
  const [monthlyNotes, setMonthlyNotes] = useState<{ [key: string]: string }>(player?.monthlyReports || {});

  const months = ["كانون الثاني", "شباط", "آذار", "نيسان", "أيار", "حزيران", "تموز", "آب", "أيلول", "تشرين الأول", "تشرين الثاني", "كانون الأول"];
  const currentMonthIndex = new Date().getMonth();
  const [selectedMonth, setSelectedMonth] = useState(months[currentMonthIndex]);

  // Fix: Implemented handleSaveMonthlyReport to persist changes to global state and database
  const handleSaveMonthlyReport = async (month: string) => {
    if (!player || !state.currentUser) return;
    const isViewer = state.currentUser.role === 'مشاهد';
    if (isViewer) return;

    setIsSavingReport(true);
    try {
      const updatedReports = { ...monthlyNotes };

      // Update global state immediately
      setState(prev => ({
        ...prev,
        people: prev.people.map(p => p.id === player.id ? { ...p, monthlyReports: updatedReports } : p)
      }));

      // Persist to Supabase
      const { error } = await supabase
        .from('people')
        .update({ monthlyReports: updatedReports })
        .eq('id', player.id);

      if (error) throw error;

      alert(`تم حفظ تقرير شهر ${month} بنجاح.`);
    } catch (err: any) {
      alert("خطأ أثناء الحفظ: " + err.message);
    } finally {
      setIsSavingReport(false);
    }
  };

  if (!player || !state.currentUser) return null;

  const isStaff = player.role !== 'لاعب';
  const isViewer = state.currentUser.role === 'مشاهد';

  // 1. حساب إحصائيات المباريات والاتجاه الزمني
  const matchStats = useMemo(() => {
    if (isStaff) return { totalMins: 0, goals: 0, assists: 0, yellows: 0, reds: 0, list: [], trend: [] };
    let totalMins = 0;
    let totalGoals = 0;
    let totalAssists = 0;
    let totalYellows = 0;
    let totalReds = 0;

    const allMatches = [...state.matches].filter(m => m.isCompleted).sort((a, b) => a.date.localeCompare(b.date));

    const statsList = allMatches.map(m => {
        const starter = m.lineup.starters.find(s => s.playerId === player.id);
        const sub = m.lineup.subs.find(s => s.playerId === player.id);
        let mins = parseInt(starter?.minutesPlayed || sub?.minutesPlayed || '0') || 0;
        totalMins += mins;
        const goals = m.events ? m.events.filter(e => e.type === 'goal' && (e.player === player.id || e.player === player.name)).length : 0;
        const assists = m.events ? m.events.filter(e => e.type === 'assist' && (e.player === player.id || e.player === player.name)).length : 0;
        const matchYellows = m.events ? m.events.filter(e => e.type === 'yellow' && (e.player === player.id || e.player === player.name)).length : 0;
        const matchReds = m.events ? m.events.filter(e => e.type === 'red' && (e.player === player.id || e.player === player.name)).length : 0;
        totalGoals += goals; totalAssists += assists; totalYellows += matchYellows; totalReds += matchReds;
        return { opponent: m.opponent, date: m.date, mins, goals, assists, yellows: matchYellows, reds: matchReds, wasStarter: !!starter, played: !!(starter || sub) };
    }).filter(s => s.played);

    // استخراج آخر 7 مباريات للرسم البياني
    const trend = statsList.slice(-7).map(s => s.mins);

    return { totalMins, goals: totalGoals, assists: totalAssists, yellows: totalYellows, reds: totalReds, list: statsList.reverse(), trend };
  }, [state.matches, player, isStaff]);

  // 2. حساب إحصائيات المقارنة مع الفئة
  const comparisonData = useMemo(() => {
    const categoryPlayers = state.people.filter(p => p.category === player.category && p.role === 'لاعب');
    const catSessions = state.sessions.filter(s => s.category === player.category);

    const getPlayerAttendance = (pid: string) => {
        const recs = state.attendance.filter(a => a.personId === pid);
        return catSessions.length > 0 ? Math.round((recs.filter(r => r.status === 'حاضر').length / catSessions.length) * 100) : 0;
    };

    const avgAttendance = Math.round(categoryPlayers.reduce((acc, p) => acc + getPlayerAttendance(p.id), 0) / (categoryPlayers.length || 1));
    const myAttendance = getPlayerAttendance(player.id);

    return { myAttendance, avgAttendance, categorySize: categoryPlayers.length };
  }, [state, player]);

  const DataRow = ({ icon: Icon, label, value, color = "text-slate-900" }: any) => (
    <div className="flex justify-between items-center py-4 border-b-2 border-slate-100 last:border-0 group transition-colors hover:bg-slate-50 px-2 rounded-lg">
      <div className="flex items-center gap-4">
        <Icon size={18} className="text-[#001F3F] drop-shadow-sm group-hover:text-orange-600 transition-colors" />
        <span className="text-[11px] font-black text-slate-500 uppercase tracking-tighter drop-shadow-sm">{label}</span>
      </div>
      <span className={`text-[12px] font-black ${color} tabular-nums drop-shadow-sm text-left`}>{value || '---'}</span>
    </div>
  );

  return (
