import React, { useState, useMemo } from 'react';
import { 
  UserPlus, Trash2, Search, Edit2, MapPin, Calendar, ChevronRight, 
  X, Save, Target, Phone, Ruler, Weight, Home, Fingerprint, 
  BadgeCheck, Edit3, Wallet, HeartPulse, ShieldAlert, 
