                    {!isViewer && (
                      <button 
                        onClick={() => handleSaveMonthlyReport(selectedMonth)} 
                        disabled={isSavingReport}
                        className="bg-emerald-600 text-white px-6 py-2.5 rounded-xl font-black text-xs shadow-lg hover:bg-emerald-700 transition-all flex items-center gap-2"
                      >
                        {isSavingReport ? <Loader2 size={16} className="animate-spin"/> : <CheckCircle size={16}/>} حفظ التقرير
