    </div>
  );
};

export default PlayerReport;

import React, { useMemo, useState } from 'react';
import { 
  ChevronRight, Printer, Target, Calendar, 
  TrendingUp, Activity, Trophy, 
  CheckCircle, Hash, User, Timer, StickyNote, 
  HeartPulse, ShieldAlert, Gavel, Wallet, 
  Phone, Fingerprint, Ruler, Weight, BadgeCheck, MapPin, 
  Globe, Briefcase, BarChart, Users, Star, AlertCircle, FileText,
  Loader2, GraduationCap, Award, Home, Info
} from 'lucide-react';
import { AppState, Person } from '../types';
import { supabase } from '../App';

interface PlayerReportProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  player: Person | null;
  onBack: () => void;
}

const PlayerReport: React.FC<PlayerReportProps> = ({ state, setState, player, onBack }) => {
  const [isSavingReport, setIsSavingReport] = useState(false);
  const [monthlyNotes, setMonthlyNotes] = useState<{ [key: string]: string }>(player?.monthlyReports || {});

  const months = ["كانون الثاني", "شباط", "آذار", "نيسان", "أيار", "حزيران", "تموز", "آب", "أيلول", "تشرين الأول", "تشرين الثاني", "كانون الأول"];
  const currentMonthIndex = new Date().getMonth();
  const [selectedMonth, setSelectedMonth] = useState(months[currentMonthIndex]);

  const handleSaveMonthlyReport = async (month: string) => {
    if (!player || !state.currentUser) return;
    if (state.currentUser.role === 'مشاهد') return;

    setIsSavingReport(true);
    try {
      const updatedReports = { ...monthlyNotes };
      setState(prev => ({
        ...prev,
        people: prev.people.map(p => p.id === player.id ? { ...p, monthlyReports: updatedReports } : p)
      }));

      const { error } = await supabase
        .from('people')
        .update({ monthlyReports: updatedReports })
        .eq('id', player.id);

      if (error) throw error;
    } catch (err: any) {
      alert("خطأ أثناء الحفظ: " + err.message);
    } finally {
      setIsSavingReport(false);
    }
  };

  if (!player || !state.currentUser) return null;

  const isStaff = player.role !== 'لاعب';
  const isViewer = state.currentUser.role === 'مشاهد';

  // حساب إحصائيات المباريات والاتجاه الزمني (آخر 7 مباريات)
  const matchStats = useMemo(() => {
    if (isStaff) return { totalMins: 0, goals: 0, assists: 0, yellows: 0, reds: 0, list: [], trend: [] };
    let totalMins = 0, totalGoals = 0, totalAssists = 0, totalYellows = 0, totalReds = 0;

    const playerMatches = state.matches
      .filter(m => m.isCompleted && m.category === player.category)
      .sort((a, b) => a.date.localeCompare(b.date));

    const statsList = playerMatches.map(m => {
        const starter = m.lineup.starters.find(s => s.playerId === player.id);
        const sub = m.lineup.subs.find(s => s.playerId === player.id);
        let mins = parseInt(starter?.minutesPlayed || sub?.minutesPlayed || '0') || 0;

        const goals = m.events.filter(e => e.type === 'goal' && (e.player === player.id || e.player === player.name)).length;
        const assists = m.events.filter(e => e.type === 'assist' && (e.player === player.id || e.player === player.name)).length;
        const yel = m.events.filter(e => e.type === 'yellow' && (e.player === player.id || e.player === player.name)).length;
        const red = m.events.filter(e => e.type === 'red' && (e.player === player.id || e.player === player.name)).length;

        totalMins += mins; totalGoals += goals; totalAssists += assists; totalYellows += yel; totalReds += red;

        return { opponent: m.opponent, date: m.date, mins, played: !!(starter || sub) };
    }).filter(s => s.played);

    const trend = statsList.slice(-7).map(s => s.mins);
    return { totalMins, goals: totalGoals, assists: totalAssists, yellows: totalYellows, reds: totalReds, list: statsList.reverse(), trend };
  }, [state.matches, player, isStaff]);

  // إصلاح منطق الالتزام - منع تجاوز 100%
  const comparison = useMemo(() => {
    const catSessions = state.sessions.filter(s => s.category === player.category && s.isCompleted);
    const catPlayers = state.people.filter(p => p.category === player.category && p.role === 'لاعب');

    const getSafeRate = (pid: string) => {
      if (catSessions.length === 0) return 0;
      const recs = state.attendance.filter(a => a.personId === pid && state.sessions.find(s => s.id === a.sessionId)?.isCompleted);
      const presentCount = recs.filter(r => r.status === 'حاضر').length;
      const lateCount = recs.filter(r => r.status === 'متأخر').length;

      // المعادلة: الحاضر (100%) + المتأخر (70%) مقسوماً على إجمالي الجلسات المكتملة
      const score = ((presentCount + (lateCount * 0.7)) / catSessions.length) * 100;
      return Math.min(100, Math.max(0, Math.round(score)));
    };

    const myRate = getSafeRate(player.id);
    const avgRate = catPlayers.length > 0 
      ? Math.round(catPlayers.reduce((acc, p) => acc + getSafeRate(p.id), 0) / catPlayers.length) 
      : 0;

    return { myRate, avgRate };
  }, [state, player]);

  const InfoBlock = ({ icon: Icon, label, value, color = "text-white" }: any) => (
    <div className="bg-white/5 border border-white/10 p-4 rounded-2xl flex flex-col gap-1 hover:bg-white/10 transition-all">
      <div className="flex items-center gap-2 text-slate-500">
        <Icon size={14} />
        <span className="text-[10px] font-bold uppercase tracking-widest">{label}</span>
      </div>
      <span className={`text-sm font-black ${color} truncate`}>{value || '---'}</span>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20 no-print" dir="rtl">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <button onClick={onBack} className="flex items-center gap-2 bg-white/5 hover:bg-orange-500 text-white px-6 py-3 rounded-2xl font-black text-sm transition-all border border-white/10 shadow-lg">
          <ChevronRight size={20} /> العودة لقائمة الفريق
        </button>
        <button onClick={() => window.print()} className="bg-white text-slate-950 px-8 py-3 rounded-2xl font-black text-sm flex items-center gap-2 hover:bg-orange-500 hover:text-white transition-all shadow-xl">
          <Printer size={18} /> تصدير الملف الفني الشامل PDF
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* RIGHT COLUMN: IDENTITY & SENSITIVE DATA */}
        <div className="lg:col-span-4 space-y-6">
           <div className="modern-card p-8 flex flex-col items-center text-center border-b-8 border-orange-500">
              <div className="relative mb-6">
                <div className="w-40 h-40 bg-slate-800 rounded-[3.5rem] flex items-center justify-center font-black text-6xl text-white border-4 border-white/10 shadow-2xl">
                   {player.name.charAt(0)}
                </div>
                <div className="absolute -bottom-4 -right-4 bg-orange-500 text-white w-14 h-14 rounded-2xl flex items-center justify-center font-black text-2xl border-4 border-[#0f172a] shadow-xl">
                   #{player.number || '0'}
                </div>
              </div>
              <h2 className="text-3xl font-black text-white tracking-tight">{player.name}</h2>
              <p className="text-orange-500 font-bold uppercase tracking-[0.2em] mt-2 bg-orange-500/10 px-4 py-1 rounded-full border border-orange-500/20">{player.role} | {player.category}</p>
           </div>

           {/* 1. البيانات الشخصية الحساسة الكاملة */}
           <div className="modern-card p-6 space-y-4">
              <h3 className="text-xs font-black text-orange-500 uppercase tracking-widest border-r-4 border-orange-500 pr-3 mb-6">1. الهوية والبيانات الشخصية</h3>
              <div className="grid grid-cols-1 gap-3">
                 <InfoBlock icon={User} label="اسم الأب الكامل" value={player.fatherName} />
                 <InfoBlock icon={User} label="اسم الأم" value={player.motherName} />
                 <InfoBlock icon={Calendar} label="تاريخ الميلاد" value={player.birthDate} />
                 <InfoBlock icon={MapPin} label="مكان الولادة" value={player.birthPlace} />
                 <InfoBlock icon={Fingerprint} label="القيد (الخانة)" value={player.khana} />
                 <InfoBlock icon={BadgeCheck} label="الرقم الوطني" value={player.nationalId} />
                 <InfoBlock icon={Hash} label="الرقم الاتحادي" value={player.federalNumber} />
                 <InfoBlock icon={Globe} label="الرقم الدولي" value={player.internationalId} color="text-orange-400" />
                 <InfoBlock icon={Phone} label="رقم التواصل" value={player.phone} />
                 <InfoBlock icon={Home} label="العنوان السكني" value={player.address} />
              </div>
           </div>

           {/* 2. البيانات العلمية والشهادات */}
           <div className="modern-card p-6 space-y-4">
              <h3 className="text-xs font-black text-blue-400 uppercase tracking-widest border-r-4 border-blue-400 pr-3 mb-6">2. التأهيل العلمي والمهني</h3>
              <div className="grid grid-cols-1 gap-3">
                 <InfoBlock icon={GraduationCap} label="الشهادة العلمية / الدرجة" value={player.academicDegree} />
                 <InfoBlock icon={Award} label="الشهادات التدريبية / الفنية" value={player.coachingCertificate} />
              </div>
           </div>
        </div>

        {/* LEFT COLUMN: PERFORMANCE, CONTRACTS & REPORTS */}
        <div className="lg:col-span-8 space-y-8">

           {/* Visual Analytics Grid */}
           <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {/* Performance Trend */}
              <div className="modern-card p-8 border-t-4 border-blue-500">
                 <h3 className="text-sm font-black text-white mb-8 flex items-center gap-2">
                    <TrendingUp size={18} className="text-blue-500" /> تحليل اتجاه دقائق المشاركة (آخر 7)
                 </h3>
                 <div className="h-40 flex items-end justify-between gap-2 px-2 border-b border-white/10 pb-2">
                    {matchStats.trend.length > 0 ? matchStats.trend.map((mins, i) => {
                       const h = Math.min(100, Math.max(10, (mins / 90) * 100));
                       return (
                         <div key={i} className="flex-1 group relative flex flex-col items-center">
                            <div className="w-full bg-blue-500/40 rounded-t-lg transition-all group-hover:bg-blue-500" style={{ height: `${h}%` }}></div>
                            <div className="absolute -top-8 bg-slate-900 text-[8px] font-bold px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap">{mins} د</div>
                            <span className="text-[8px] font-bold text-slate-500 mt-2">M{i+1}</span>
                         </div>
                       );
                    }) : <p className="w-full h-full flex items-center justify-center italic text-slate-600 text-xs">لا توجد بيانات مشاركة</p>}
                 </div>
              </div>

              {/* Corrected Attendance Score */}
              <div className="modern-card p-8 border-t-4 border-emerald-500">
                 <h3 className="text-sm font-black text-white mb-8 flex items-center gap-2">
                    <Users size={18} className="text-emerald-500" /> مؤشر الانضباط (بالمئة %)
                 </h3>
                 <div className="space-y-6">
                    <div className="space-y-2">
                       <div className="flex justify-between text-[10px] font-black uppercase">
                          <span>التزام اللاعب الفعلي</span>
                          <span className="text-emerald-500">%{comparison.myRate}</span>
                       </div>
                       <div className="h-3 bg-white/5 rounded-full overflow-hidden border border-white/5">
                          <div className={`h-full transition-all duration-1000 ${comparison.myRate > 80 ? 'bg-emerald-500' : 'bg-orange-500'}`} style={{ width: `${comparison.myRate}%` }}></div>
                       </div>
                    </div>
                    <div className="space-y-2">
                       <div className="flex justify-between text-[10px] font-black uppercase">
                          <span>متوسط التزام الفئة</span>
                          <span className="text-blue-400">%{comparison.avgRate}</span>
                       </div>
                       <div className="h-2 bg-white/5 rounded-full overflow-hidden border border-white/5">
                          <div className="h-full bg-blue-500 transition-all duration-1000" style={{ width: `${comparison.avgRate}%` }}></div>
                       </div>
                    </div>
                    <div className="bg-slate-900/50 p-4 rounded-xl border border-white/10 flex items-center gap-3">
                       <Info size={16} className="text-orange-500" />
                       <p className="text-[10px] font-bold text-slate-400">تحتسب النسبة بناءً على الحضور الكامل (100%) والتأخير (70%) مقارنة بإجمالي الحصص المكتملة.</p>
                    </div>
                 </div>
              </div>
           </div>

           {/* 3. السجل التعاقدي والمالي الكامل */}
           <div className="modern-card p-8 border-r-8 border-yellow-500">
              <h3 className="text-lg font-black text-white mb-8 flex items-center gap-3">
                 <Gavel size={24} className="text-yellow-500" /> 3. السجل التعاقدي والمالي
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
