              <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 border-b border-white/5 pb-6">
                 <div>
                    <h3 className="text-xl font-black text-white flex items-center gap-3">
                       <StickyNote size={24} className="text-blue-500" /> 6. التقرير الفني والمسلكي الشهري
                    </h3>
                    <p className="text-[10px] font-bold text-slate-500 uppercase mt-1">أرشفة الملاحظات الدورية للمدير الفني</p>
                 </div>
                 {!isViewer && (
                    <button 
                      onClick={() => handleSaveMonthlyReport(selectedMonth)} 
                      disabled={isSavingReport}
                      className="bg-emerald-600 text-white px-6 py-2.5 rounded-xl font-black text-xs shadow-lg hover:bg-emerald-700 transition-all flex items-center gap-2"
                    >
                      {isSavingReport ? <Loader2 size={16} className="animate-spin"/> : <CheckCircle size={16}/>} حفظ تقرير الشهر
                    </button>
                 )}
              </div>

              <div className="flex gap-2 mb-6 overflow-x-auto pb-4 custom-scrollbar">
                 {months.map(m => (
                   <button key={m} onClick={() => setSelectedMonth(m)} className={`px-4 py-2 rounded-xl font-black text-[10px] whitespace-nowrap transition-all border ${selectedMonth === m ? 'bg-orange-500 text-white border-orange-500 shadow-lg scale-105' : 'bg-white/5 text-slate-500 border-white/10 hover:bg-white/10'}`}>
                     {m}
                   </button>
                 ))}
              </div>

              <textarea 
                 className="w-full bg-slate-900/80 border border-white/10 rounded-[2rem] p-8 text-sm font-medium text-slate-200 h-64 resize-none outline-none focus:border-orange-500 transition-all shadow-inner"
                 placeholder={`سجل انطباعك الفني عن اللاعب لشهر ${selectedMonth}...`}
                 value={monthlyNotes[selectedMonth] || ""}
                 onChange={e => setMonthlyNotes({...monthlyNotes, [selectedMonth]: e.target.value})}
                 readOnly={isViewer}
              ></textarea>
           </div>

           {/* 7. ملاحظات عامة إضافية */}
           <div className="modern-card p-8 bg-slate-900/40">
              <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest mb-4">7. ملاحظات إدارية وعامة</h3>
              <p className="text-sm font-bold text-slate-300 leading-relaxed italic border-r-2 border-slate-700 pr-4">
                 {player.notes || "لا توجد ملاحظات إضافية."}
              </p>
           </div>

        </div>
      </div>
    </div>
  );
};

