                <p className="flex items-center gap-2"><Calendar size={12}/> {person.birthDate || '---'}</p>
                {person.position && <p className="flex items-center gap-2 text-orange-500/80 uppercase"><Target size={12}/> {person.position}</p>}
             </div>
