                 <InfoBlock icon={Phone} label="رقم التواصل" value={player.phone} />
                 <InfoBlock icon={Home} label="العنوان" value={player.address} />
              </div>
           </div>

           <div className="modern-card p-6 space-y-4">
              <h3 className="text-xs font-black text-blue-400 uppercase tracking-widest border-r-4 border-blue-400 pr-3 mb-6">2. البيانات الأكاديمية</h3>
              <div className="grid grid-cols-1 gap-3">
                 <InfoBlock icon={GraduationCap} label="الشهادة العلمية" value={player.academicDegree} />
