        {/* Left: Performance & Technical Data */}
        <div className="lg:col-span-8 space-y-8">
           <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {/* Performance Graph */}
              <div className="modern-card p-8 border-t-4 border-blue-500">
                 <h3 className="text-sm font-black text-white mb-8 flex items-center gap-2">
                    <TrendingUp size={18} className="text-blue-500" /> تحليل دقائق اللعب (آخر 7)
                 </h3>
                 <div className="h-40 flex items-end justify-between gap-2 px-2 border-b border-white/10 pb-2">
                    {matchStats.trend.length > 0 ? matchStats.trend.map((mins, i) => (
                       <div key={i} className="flex-1 group relative flex flex-col items-center">
                          <div className="w-full bg-blue-500/40 rounded-t-lg transition-all group-hover:bg-blue-500" style={{ height: `${Math.max(10, (mins/90)*100)}%` }}></div>
                          <span className="text-[8px] font-bold text-slate-500 mt-2">M{i+1}</span>
                       </div>
                    )) : <p className="text-xs italic text-slate-600 w-full text-center">لا توجد بيانات</p>}
                 </div>
              </div>

              {/* Attendance Score */}
              <div className="modern-card p-8 border-t-4 border-emerald-500">
                 <h3 className="text-sm font-black text-white mb-8 flex items-center gap-2">
                    <Users size={18} className="text-emerald-500" /> مؤشر الانضباط (100%)
                 </h3>
                 <div className="space-y-6">
                    <div className="space-y-2">
                       <div className="flex justify-between text-[10px] font-black">
