                          <span className="text-emerald-500">%{comparison.myRate}</span>
                       </div>
                       <div className="h-3 bg-white/5 rounded-full overflow-hidden">
                          <div className="h-full bg-emerald-500" style={{ width: `${comparison.myRate}%` }}></div>
                       </div>
                    </div>
                    <div className="bg-slate-900/50 p-4 rounded-xl border border-white/10">
                       <p className="text-[10px] font-bold text-slate-400">متوسط التزام الفئة العام هو %{comparison.avgRate}.</p>
                    </div>
                 </div>
              </div>
           </div>

           {/* Financial & Contracts */}
           <div className="modern-card p-8 border-r-8 border-yellow-500">
              <h3 className="text-lg font-black text-white mb-8 flex items-center gap-3">
                 <Gavel size={24} className="text-yellow-500" /> 3. السجل التعاقدي والمالي
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                 <div className="bg-slate-900/80 p-6 rounded-3xl border border-white/5">
                    <p className="text-[9px] font-black text-slate-500 mb-2">قيمة العقد</p>
                    <p className="text-2xl font-black text-emerald-400">{player.contractValue || 'غير محدد'}</p>
