                 <div className="bg-slate-900/80 p-6 rounded-3xl border border-white/5">
                    <p className="text-[9px] font-black text-slate-500 mb-2">تاريخ البدء</p>
                    <p className="text-xl font-black text-white">{player.contractStart || '---'}</p>
                 </div>
                 <div className="bg-slate-900/80 p-6 rounded-3xl border border-white/5">
                    <p className="text-[9px] font-black text-slate-500 mb-2">تاريخ النهاية</p>
                    <p className="text-xl font-black text-red-400">{player.contractEnd || '---'}</p>
                 </div>
              </div>
           </div>

           {/* Health & Medical */}
           <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="modern-card p-8 border-r-8 border-red-500">
                 <h3 className="text-lg font-black text-white mb-6 flex items-center gap-3">
                    <HeartPulse size={24} className="text-red-500" /> 4. السجل الطبي والبدني
                 </h3>
                 <div className="space-y-6">
                    <InfoBlock icon={HeartPulse} label="التاريخ الطبي" value={player.medicalHistory} />
                    <InfoBlock icon={Activity} label="الإصابات الحالية" value={player.injuries} />
                    <div className="grid grid-cols-2 gap-4">
                       <div className="bg-white/5 p-4 rounded-2xl border border-white/10 text-center">
                          <p className="text-[9px] font-black text-slate-500">الطول</p>
                          <p className="text-xl font-black">{player.height || '---'}</p>
                       </div>
                       <div className="bg-white/5 p-4 rounded-2xl border border-white/10 text-center">
                          <p className="text-[9px] font-black text-slate-500">الوزن</p>
                          <p className="text-xl font-black">{player.weight || '---'}</p>
                       </div>
                    </div>
                 </div>
              </div>

              <div className="modern-card p-8 border-r-8 border-orange-500">
                 <h3 className="text-lg font-black text-white mb-6 flex items-center gap-3">
                    <BarChart size={24} className="text-orange-500" /> 5. إحصائيات الموسم
                 </h3>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="bg-white/5 p-5 rounded-3xl text-center">
                       <p className="text-[8px] font-black text-slate-500">دقائق لعب</p>
                       <p className="text-3xl font-black">{matchStats.totalMins}</p>
                    </div>
                    <div className="bg-white/5 p-5 rounded-3xl text-center">
                       <p className="text-[8px] font-black text-slate-500">أهداف</p>
                       <p className="text-3xl font-black text-white">{matchStats.goals}</p>
                    </div>
                    <div className="bg-white/5 p-5 rounded-3xl text-center">
                       <p className="text-[8px] font-black text-slate-500">إنذار 🟨</p>
                       <p className="text-3xl font-black text-white">{matchStats.yellows}</p>
                    </div>
                    <div className="bg-white/5 p-5 rounded-3xl text-center">
                       <p className="text-[8px] font-black text-slate-500">طرد 🟥</p>
                       <p className="text-3xl font-black text-white">{matchStats.reds}</p>
