                 <div className="mt-6">
                    <p className="text-[10px] font-black text-slate-500 mb-2">سجل العقوبات</p>
                    <p className="text-xs font-bold text-red-500 bg-red-500/5 p-4 rounded-2xl border border-red-500/10">
                       {player.penalties || "السجل نظيف."}
                    </p>
