              </div>
           </div>

           {/* Monthly Report */}
           <div className="modern-card p-8">
              <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 border-b border-white/5 pb-6">
                 <div>
                    <h3 className="text-xl font-black text-white flex items-center gap-3">
                       <StickyNote size={24} className="text-blue-500" /> 6. التقرير الفني الشهري
                    </h3>
                    <p className="text-[10px] text-slate-500 uppercase mt-1">ملاحظات المدير الفني الدورية</p>
                 </div>
                 {!isViewer && (
                    <button onClick={() => handleSaveMonthlyReport(selectedMonth)} disabled={isSavingReport} className="bg-emerald-600 text-white px-6 py-2.5 rounded-xl font-black text-xs shadow-lg hover:bg-emerald-700 flex items-center gap-2">
                      {isSavingReport ? <Loader2 size={16} className="animate-spin"/> : <CheckCircle size={16}/>} حفظ التقرير
