                <div className="space-y-1"><label className={labelClass}>الفئة</label><select disabled={!isManager} className={inputClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}><option value="">اختر الفئة</option>{state.categories.map(c => <option key={c} value={c}>{c}</option>)}</select></div>
                <div className="space-y-1"><label className={labelClass}>رقم القميص</label><input type="number" className={inputClass} value={formData.number || ''} onChange={e => setFormData({...formData, number: parseInt(e.target.value)})} /></div>
                <div className="space-y-1"><label className={labelClass}>المركز</label><input className={inputClass} value={formData.position || ''} onChange={e => setFormData({...formData, position: e.target.value})} /></div>
              </div>

              <h4 className={sectionTitle}>3. البيانات التعاقدية والمالية</h4>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="space-y-1"><label className={labelClass}><Calendar size={12}/> بداية العقد</label><input type="date" className={inputClass} value={formData.contractStart || ''} onChange={e => setFormData({...formData, contractStart: e.target.value})} /></div>
                <div className="space-y-1"><label className={labelClass}><Calendar size={12}/> نهاية العقد</label><input type="date" className={inputClass} value={formData.contractEnd || ''} onChange={e => setFormData({...formData, contractEnd: e.target.value})} /></div>
                <div className="space-y-1"><label className={labelClass}><Wallet size={12}/> قيمة العقد</label><input className={inputClass} value={formData.contractValue || ''} onChange={e => setFormData({...formData, contractValue: e.target.value})} placeholder="القيمة المادية..." /></div>
              </div>

              <h4 className={sectionTitle}>4. السجل الطبي والبدني</h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1"><label className={labelClass}><HeartPulse size={12}/> السجل الطبي</label><textarea className={inputClass + " h-20"} value={formData.medicalHistory || ''} onChange={e => setFormData({...formData, medicalHistory: e.target.value})} /></div>
                <div className="space-y-1"><label className={labelClass}><Activity size={12}/> سجل الإصابات</label><textarea className={inputClass + " h-20"} value={formData.injuries || ''} onChange={e => setFormData({...formData, injuries: e.target.value})} /></div>
              </div>

              <h4 className={sectionTitle}>5. الانضباط والمؤهلات</h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1"><label className={labelClass}><ShieldAlert size={12}/> سجل العقوبات</label><textarea className={inputClass + " h-20"} value={formData.penalties || ''} onChange={e => setFormData({...formData, penalties: e.target.value})} /></div>
                <div className="space-y-1"><label className={labelClass}><Award size={12}/> الشهادات التدريبية</label><input className={inputClass} value={formData.coachingCertificate || ''} onChange={e => setFormData({...formData, coachingCertificate: e.target.value})} /></div>
                <div className="space-y-1"><label className={labelClass}><GraduationCap size={12}/> الشهادة العلمية</label><input className={inputClass} value={formData.academicDegree || ''} onChange={e => setFormData({...formData, academicDegree: e.target.value})} /></div>
                <div className="space-y-1"><label className={labelClass}><Phone size={12}/> رقم الهاتف</label><input className={inputClass} value={formData.phone || ''} onChange={e => setFormData({...formData, phone: e.target.value})} /></div>
              </div>

              <div className="pt-10">
                <button type="submit" disabled={isSaving} className="w-full bg-orange-500 text-white py-6 rounded-2xl font-black text-xl shadow-xl hover:bg-orange-600 transition-all flex items-center justify-center gap-3 border-b-8 border-orange-900 active:translate-y-1 active:border-b-0">
                  {isSaving ? <Loader2 size={24} className="animate-spin" /> : <Save size={24}/>} 
                  {editingId ? 'تثبيت التحديثات في السحابة' : 'تسجيل العضو الجديد'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

