              <div className="flex gap-2 mb-6 overflow-x-auto pb-4 custom-scrollbar">
                 {months.map(m => (
                   <button key={m} onClick={() => setSelectedMonth(m)} className={`px-4 py-2 rounded-xl font-black text-[10px] whitespace-nowrap border transition-all ${selectedMonth === m ? 'bg-orange-500 text-white border-orange-500 shadow-md scale-105' : 'bg-white/5 text-slate-500 border-white/10 hover:bg-white/10'}`}>
                     {m}
                   </button>
                 ))}
              </div>

              <textarea 
                 className="w-full bg-slate-900/80 border border-white/10 rounded-[2rem] p-8 text-sm font-medium text-slate-200 h-64 resize-none outline-none focus:border-orange-500 transition-all shadow-inner"
                 placeholder={`سجل انطباعك الفني عن اللاعب لشهر ${selectedMonth}...`}
                 value={monthlyNotes[selectedMonth] || ""}
                 onChange={e => setMonthlyNotes({...monthlyNotes, [selectedMonth]: e.target.value})}
                 readOnly={isViewer}
              ></textarea>
           </div>

           {/* 7. ملاحظات عامة */}
           <div className="modern-card p-8 bg-slate-900/40 shadow-sm border border-white/5">
              <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest mb-4">7. ملاحظات إدارية وعامة إضافية</h3>
              <p className="text-sm font-bold text-slate-300 leading-relaxed italic border-r-2 border-slate-700 pr-4">
                 {player.notes || "لا توجد ملاحظات إضافية مسجلة."}
              </p>
           </div>
        </div>
      </div>
    </div>
  );
};

