              <h4 className={sectionTitle}>4. السجل الطبي والبدني</h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1"><label className={labelClass}><HeartPulse size={12}/> السجل الطبي</label><textarea className={inputClass + " h-20"} value={formData.medicalHistory || ''} onChange={e => setFormData({...formData, medicalHistory: e.target.value})} /></div>
                <div className="space-y-1"><label className={labelClass}><Activity size={12}/> سجل الإصابات</label><textarea className={inputClass + " h-20"} value={formData.injuries || ''} onChange={e => setFormData({...formData, injuries: e.target.value})} /></div>
