import React, { useMemo, useState } from 'react';
import { 
  ChevronRight, Printer, Target, Calendar, 
  TrendingUp, Activity, Trophy, 
  CheckCircle, Hash, User, Timer, StickyNote, 
  HeartPulse, ShieldAlert, Gavel, Wallet, 
  Phone, Fingerprint, Ruler, Weight, BadgeCheck, MapPin, 
  Globe, Briefcase, BarChart, Users, Star, AlertCircle, FileText,
  Loader2, GraduationCap, Award, Home, Info
} from 'lucide-react';
import { AppState, Person } from '../types';
import { supabase } from '../App';

interface PlayerReportProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  player: Person | null;
  onBack: () => void;
}

const PlayerReport: React.FC<PlayerReportProps> = ({ state, setState, player, onBack }) => {
  const [isSavingReport, setIsSavingReport] = useState(false);
  const [monthlyNotes, setMonthlyNotes] = useState<{ [key: string]: string }>(player?.monthlyReports || {});

  const months = ["كانون الثاني", "شباط", "آذار", "نيسان", "أيار", "حزيران", "تموز", "آب", "أيلول", "تشرين الأول", "تشرين الثاني", "كانون الأول"];
  const currentMonthIndex = new Date().getMonth();
  const [selectedMonth, setSelectedMonth] = useState(months[currentMonthIndex]);

  const handleSaveMonthlyReport = async (month: string) => {
    if (!player || !state.currentUser) return;
    if (state.currentUser.role === 'مشاهد') return;

    setIsSavingReport(true);
    try {
      const updatedReports = { ...monthlyNotes };
      setState(prev => ({
        ...prev,
        people: prev.people.map(p => p.id === player.id ? { ...p, monthlyReports: updatedReports } : p)
      }));

      const { error } = await supabase
        .from('people')
        .update({ monthlyReports: updatedReports })
        .eq('id', player.id);

      if (error) throw error;
      alert(`تم حفظ تقرير شهر ${month} بنجاح.`);
    } catch (err: any) {
      alert("خطأ أثناء الحفظ: " + err.message);
    } finally {
      setIsSavingReport(false);
    }
  };

  if (!player || !state.currentUser) return null;

  const isStaff = player.role !== 'لاعب';
  const isViewer = state.currentUser.role === 'مشاهد';

  // 1. إحصائيات الأداء والمباريات
  const matchStats = useMemo(() => {
    if (isStaff) return { totalMins: 0, goals: 0, assists: 0, yellows: 0, reds: 0, trend: [] };
    let totalMins = 0, totalGoals = 0, totalAssists = 0, totalYellows = 0, totalReds = 0;

    const playerMatches = state.matches
      .filter(m => m.isCompleted && m.category === player.category)
      .sort((a, b) => a.date.localeCompare(b.date));

    const statsList = playerMatches.map(m => {
        const starter = m.lineup.starters.find(s => s.playerId === player.id);
        const sub = m.lineup.subs.find(s => s.playerId === player.id);
        let mins = parseInt(starter?.minutesPlayed || sub?.minutesPlayed || '0') || 0;

        totalMins += mins;
        totalGoals += m.events.filter(e => e.type === 'goal' && (e.player === player.id || e.player === player.name)).length;
        totalAssists += m.events.filter(e => e.type === 'assist' && (e.player === player.id || e.player === player.name)).length;
        totalYellows += m.events.filter(e => e.type === 'yellow' && (e.player === player.id || e.player === player.name)).length;
        totalReds += m.events.filter(e => e.type === 'red' && (e.player === player.id || e.player === player.name)).length;

        return { mins, played: !!(starter || sub) };
    }).filter(s => s.played);

    return { totalMins, goals: totalGoals, assists: totalAssists, yellows: totalYellows, reds: totalReds, trend: statsList.slice(-7).map(s => s.mins) };
  }, [state.matches, player, isStaff]);

  // 2. تصحيح نسبة الالتزام - قفل عند حد أقصى 100%
  const comparison = useMemo(() => {
    const catSessions = state.sessions.filter(s => s.category === player.category && s.isCompleted);
    const catPlayers = state.people.filter(p => p.category === player.category && p.role === 'لاعب');

    const calculateRate = (pid: string) => {
      if (catSessions.length === 0) return 0;
      const recs = state.attendance.filter(a => a.personId === pid);
      const present = recs.filter(r => r.status === 'حاضر').length;
      const late = recs.filter(r => r.status === 'متأخر').length;

      const score = ((present + (late * 0.7)) / catSessions.length) * 100;
      return Math.min(100, Math.round(score)); 
    };

    const myRate = calculateRate(player.id);
    const avgRate = catPlayers.length > 0 
      ? Math.round(catPlayers.reduce((acc, p) => acc + calculateRate(p.id), 0) / catPlayers.length)
      : 0;

    return { myRate, avgRate };
  }, [state, player]);

  const InfoBlock = ({ icon: Icon, label, value, color = "text-white" }: any) => (
    <div className="bg-white/5 border border-white/10 p-4 rounded-2xl flex flex-col gap-1 hover:bg-white/10 transition-all group">
      <div className="flex items-center gap-2 text-slate-500 group-hover:text-orange-500">
        <Icon size={14} />
        <span className="text-[10px] font-black uppercase tracking-widest">{label}</span>
      </div>
      <span className={`text-sm font-black ${color} truncate`}>{value || '---'}</span>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20 no-print" dir="rtl">
      {/* Header */}
      <div className="flex justify-between items-center">
        <button onClick={onBack} className="flex items-center gap-2 bg-white/5 hover:bg-orange-500 text-white px-6 py-3 rounded-2xl font-black text-sm transition-all border border-white/10 shadow-lg">
          <ChevronRight size={20} /> العودة
        </button>
        <button onClick={() => window.print()} className="bg-white text-slate-950 px-8 py-3 rounded-2xl font-black text-sm flex items-center gap-2 hover:bg-orange-500 hover:text-white transition-all shadow-xl">
          <Printer size={18} /> طباعة الملف الفني
        </button>
      </div>

