                 <InfoBlock icon={User} label="اسم الأم" value={player.motherName} />
                 <InfoBlock icon={Calendar} label="تاريخ الميلاد" value={player.birthDate} />
                 <InfoBlock icon={MapPin} label="مكان الولادة" value={player.birthPlace} />
                 <InfoBlock icon={Fingerprint} label="القيد" value={player.khana} />
                 <InfoBlock icon={BadgeCheck} label="الرقم الوطني" value={player.nationalId} />
                 <InfoBlock icon={Hash} label="الرقم الاتحادي" value={player.federalNumber} />
                 <InfoBlock icon={Globe} label="الرقم الدولي" value={player.internationalId} />
                 <InfoBlock icon={Phone} label="الهاتف" value={player.phone} />
                 <InfoBlock icon={Home} label="العنوان" value={player.address} />
              </div>
           </div>

           <div className="modern-card p-6 space-y-4">
              <h3 className="text-xs font-black text-blue-400 uppercase tracking-widest border-r-4 border-blue-400 pr-3 mb-6">2. البيانات العلمية</h3>
              <div className="grid grid-cols-1 gap-3">
                 <InfoBlock icon={GraduationCap} label="الشهادة العلمية" value={player.academicDegree} />
                 <InfoBlock icon={Award} label="الشهادة التدريبية" value={player.coachingCertificate} />
              </div>
           </div>
        </div>

        {/* Left: Performance, Contracts & Administrative */}
        <div className="lg:col-span-8 space-y-8">
           <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="modern-card p-8 border-t-4 border-emerald-500">
                 <h3 className="text-sm font-black text-white mb-8 flex items-center gap-2">
                    <Users size={18} className="text-emerald-500" /> الانضباط (100%)
                 </h3>
                 <div className="space-y-6">
                    <div className="space-y-2">
                       <div className="flex justify-between text-[10px] font-black">
                          <span>التزام اللاعب</span>
                          <span className="text-emerald-500">%{comparison.myRate}</span>
                       </div>
                       <div className="h-3 bg-white/5 rounded-full overflow-hidden">
                          <div className="h-full bg-emerald-500" style={{ width: `${comparison.myRate}%` }}></div>
                       </div>
                    </div>
                 </div>
              </div>
              <div className="modern-card p-8 border-t-4 border-blue-500">
                 <h3 className="text-sm font-black text-white mb-8 flex items-center gap-2">
                    <BarChart size={18} className="text-blue-500" /> إحصائيات الموسم
                 </h3>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="text-center bg-white/5 p-4 rounded-xl">
                       <p className="text-[10px] text-slate-500">أهداف</p>
                       <p className="text-2xl font-black">{matchStats.goals}</p>
                    </div>
                    <div className="text-center bg-white/5 p-4 rounded-xl">
                       <p className="text-[10px] text-slate-500">دقائق</p>
                       <p className="text-2xl font-black">{matchStats.totalMins}</p>
                    </div>
                 </div>
              </div>
           </div>

           <div className="modern-card p-8 border-r-8 border-yellow-500">
              <h3 className="text-lg font-black text-white mb-8 flex items-center gap-3">
                 <Gavel size={24} className="text-yellow-500" /> 3. السجل التعاقدي
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                 <InfoBlock icon={Wallet} label="قيمة العقد" value={player.contractValue} color="text-emerald-400" />
                 <InfoBlock icon={Calendar} label="بداية العقد" value={player.contractStart} />
                 <InfoBlock icon={Calendar} label="نهاية العقد" value={player.contractEnd} color="text-red-400" />
              </div>
           </div>

           <div className="modern-card p-8 border-r-8 border-red-500">
              <h3 className="text-lg font-black text-white mb-6 flex items-center gap-3">
                 <HeartPulse size={24} className="text-red-500" /> 4. الحالة الصحية
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <InfoBlock icon={HeartPulse} label="التاريخ الطبي" value={player.medicalHistory} />
                 <InfoBlock icon={Activity} label="الإصابات" value={player.injuries} color="text-orange-400" />
              </div>
           </div>

           <div className="modern-card p-8">
              <h3 className="text-xl font-black text-white flex items-center gap-3 mb-8">
                 <StickyNote size={24} className="text-blue-500" /> 5. التقرير الشهري
              </h3>
              <textarea 
                 className="w-full bg-slate-900 border border-white/10 rounded-2xl p-6 text-sm text-slate-200 h-48 resize-none outline-none focus:border-orange-500 transition-all"
                 placeholder={`ملاحظات شهر ${selectedMonth}...`}
                 value={monthlyNotes[selectedMonth] || ""}
                 onChange={e => setMonthlyNotes({...monthlyNotes, [selectedMonth]: e.target.value})}
                 readOnly={isViewer}
              ></textarea>
              {!isViewer && (
                <button onClick={() => handleSaveMonthlyReport(selectedMonth)} disabled={isSavingReport} className="mt-4 bg-emerald-600 text-white px-6 py-2.5 rounded-xl font-black text-xs flex items-center gap-2">
                  {isSavingReport ? <Loader2 size={16} className="animate-spin"/> : <CheckCircle size={16}/>} حفظ تقرير {selectedMonth}
                </button>
              )}
           </div>

           <div className="modern-card p-8 border-r-8 border-slate-700">
              <h3 className="text-xs font-black text-slate-500 uppercase mb-4">6. ملاحظات إدارية وعقوبات</h3>
              <div className="space-y-4">
                 <div className="bg-red-500/5 p-4 rounded-xl border border-red-500/10">
                    <p className="text-[10px] font-black text-red-500 mb-1">سجل العقوبات</p>
                    <p className="text-sm font-bold text-red-200">{player.penalties || 'لا يوجد سجل عقوبات.'}</p>
                 </div>
                 <div className="bg-white/5 p-4 rounded-xl border border-white/10">
                    <p className="text-[10px] font-black text-slate-500 mb-1">ملاحظات عامة</p>
                    <p className="text-sm font-bold text-slate-300">{player.notes || 'لا توجد ملاحظات إضافية.'}</p>
                 </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default PlayerReport;

