          >
            {loading ? <Loader2 className="animate-spin" /> : <Search size={24} />}
            بحث
          </button>
        </div>
      </div>

      {response && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in slide-in-from-bottom-6 duration-500">
