            <div className="space-y-3 max-h-[600px] overflow-y-auto custom-scrollbar pr-2">
              {response.links.length > 0 ? response.links.map((link, i) => (
                <a 
                  key={i} 
                  href={link.uri} 
                  target="_blank" 
