                    <button onClick={() => setReportType('player')} className={`w-full py-3 rounded-lg font-black text-[10px] transition-all ${reportType === 'player' ? 'bg-[#001F3F] text-white shadow-md' : 'text-slate-50'}`}>👤 تقرير التزام عضو واحد</button>
