import SettingsView from './components/SettingsView';
import PlayerReport from './components/PlayerReport';
import WarehouseManagement from './components/WarehouseManagement';
import Login from './components/Login';
import ClubLogo from './components/ClubLogo';
import AIAssistant from './components/AIAssistant';
import ChatBot from './components/ChatBot';
import TacticalBoard from './components/TacticalBoard';
import MedicalCenter from './components/MedicalCenter';
import QRManager from './components/QRManager';
import VisualAnalytics from './components/VisualAnalytics';
import LocationAssistant from './components/LocationAssistant';

export const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

export const supabase = createClient(
  'https://kfwqoigsghlgigjriyxf.supabase.co',
  'sb_publishable_O2vR2yKUG-FVeaydD4z6Lg_tjFcKDic'
);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'error' | 'syncing'>('synced');
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_central_v2');
    if (saved) { try { return JSON.parse(saved); } catch (e) {} }
    return {
      currentUser: null, categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [], sessions: [], matches: [], warehouse: [], technicalReports: [],
      attendance: [], users: [], notifications: [], globalCategoryFilter: 'الكل',
      injuries: [], tacticalPlans: []
    };
  });

  const addNotify = useCallback((message: string, type: AppNotification['type'] = 'info') => {
    const id = generateUUID();
    setNotifications(prev => [{ id, message, type, timestamp: Date.now() }, ...prev].slice(0, 3));
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 3000);
  }, []);

  const fetchAllData = useCallback(async (user: AppUser) => {
    setSyncStatus('syncing');
    try {
      const isManager = user.role === 'مدير';
      const cat = user.restrictedCategory;

      let peopleQ = supabase.from('people').select('*');
      let matchesQ = supabase.from('matches').select('*');
      let sessionsQ = supabase.from('sessions').select('*');
      let attendanceQ = supabase.from('attendance').select('*');
      let warehouseQ = supabase.from('warehouse').select('*');
      let usersQ = supabase.from('app_users').select('*');

      if (!isManager && cat) {
        peopleQ = peopleQ.eq('category', cat);
        matchesQ = matchesQ.eq('category', cat);
        sessionsQ = sessionsQ.eq('category', cat);
        warehouseQ = warehouseQ.or(`category.eq.${cat},category.eq.المخزن العام`);
      }

      const [p, m, s, a, w, u] = await Promise.all([
        peopleQ, matchesQ, sessionsQ, attendanceQ, warehouseQ, usersQ
      ]);

      setState(prev => ({
        ...prev,
        currentUser: user,
        people: p.data || [],
        matches: m.data || [],
        sessions: s.data || [],
        attendance: a.data || [],
        warehouse: w.data || [],
        users: u.data || [],
        globalCategoryFilter: (!isManager && cat) ? cat : 'الكل'
      }));
      setSyncStatus('synced');
    } catch (e) {
      setSyncStatus('error');
    }
  }, []);

  useEffect(() => {
    if (!state.currentUser) return;

    const channel = supabase.channel('global-changes')
      .on('postgres_changes', { event: '*', schema: 'public' }, (payload) => {
        fetchAllData(state.currentUser!);
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [state.currentUser, fetchAllData]);

  useEffect(() => {
    if (state.currentUser) {
      localStorage.setItem('alkarama_central_v2', JSON.stringify(state));
    }
  }, [state]);

  const updateState = (updater: (prev: AppState) => AppState) => {
    setState(prev => updater(prev));
  };

  const onLoginAttempt = async (u: string, p: string) => {
    setSyncStatus('syncing');
    if ((u.trim() === 'عزت' || u.toUpperCase() === 'IZZAT') && p === '123') {
      const rootUser: AppUser = { id: 'root', username: 'عزت عامر الشيخة', role: 'مدير' };
      await fetchAllData(rootUser);
      return rootUser;
    }

    const { data } = await supabase.from('app_users').select('*').eq('username', u).eq('password', p).maybeSingle();
    if (!data) {
      setSyncStatus('error');
      return null;
    }
    await fetchAllData(data);
    return data;
  };

  const getPlayerSuspension = useCallback((playerId: string, category: string) => {
    const playerMatches = state.matches
      .filter(m => m.category === category && m.isCompleted)
      .sort((a, b) => a.date.localeCompare(b.date));

    let accumulatedYellows = 0;
    let hasActiveRed = false;
    let suspendedForNext = false;

    playerMatches.forEach(m => {
      const matchYellows = m.events.filter(e => e.type === 'yellow' && (e.player === playerId)).length;
      const matchRed = m.events.some(e => e.type === 'red' && (e.player === playerId));

      if (hasActiveRed) {
        suspendedForNext = true;
        hasActiveRed = false;
      } else if (accumulatedYellows >= 3) {
        suspendedForNext = true;
        accumulatedYellows = 0;
      } else {
        suspendedForNext = false;
      }

      accumulatedYellows += matchYellows;
      if (matchRed) hasActiveRed = true;
    });

    return { 
      isSuspended: suspendedForNext || hasActiveRed, 
      currentYellows: accumulatedYellows,
      hasActiveRed
    };
  }, [state.matches]);

  if (!state.currentUser) return <Login onLoginAttempt={onLoginAttempt} />;

  const navItems = [
    { id: 'dashboard', label: 'الرئيسية', icon: LayoutDashboard },
    { id: 'squad', label: 'الفريق', icon: Users },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'attendance', label: 'الحضور', icon: ClipboardCheck },
    { id: 'tactics', label: 'التكتيك', icon: PenTool },
    { id: 'medical', label: 'الطبابة', icon: HeartPulse },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'logistics', label: 'المساعد اللوجستي', icon: Compass },
    { id: 'warehouse', label: 'المستودع', icon: Package },
    { id: 'qr', label: 'نظام QR', icon: QrCode },
    { id: 'analytics', label: 'التحليلات', icon: Activity },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ].filter(item => {
    if (state.currentUser?.role !== 'مدير' && item.id === 'settings') return false;
    return true;
  });

  return (
    <div className="flex h-screen bg-[#020617] text-[#f8fafc] font-['IBM_Plex_Sans_Arabic'] overflow-hidden" dir="rtl">
      <aside className={`${isSidebarOpen ? 'w-72' : 'w-24'} bg-[#0f172a] border-l border-white/5 transition-all duration-300 flex flex-col z-50 shadow-2xl`}>
        <div className="p-8 flex items-center justify-center gap-4">
           <ClubLogo size={isSidebarOpen ? 50 : 35} />
           {isSidebarOpen && <span className="text-xl font-black text-white tracking-tight bg-gradient-to-r from-orange-500 to-white bg-clip-text text-transparent">Eagle OS</span>}
        </div>

        <nav className="flex-1 px-4 space-y-1 overflow-y-auto custom-scrollbar">
          {navItems.map(item => (
            <button key={item.id} onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200
              ${activeTab === item.id ? 'bg-orange-500 text-white shadow-lg shadow-orange-500/20' : 'hover:bg-white/5 text-slate-400 hover:text-white'}`}>
              <item.icon size={20} />
              {isSidebarOpen && <span className="text-sm font-medium">{item.label}</span>}
            </button>
          ))}
        </nav>

        <div className="p-4 mt-auto">
          <div className="bg-white/5 rounded-xl p-3 mb-4 flex items-center gap-3">
             <div className="w-8 h-8 rounded-full bg-orange-500 flex items-center justify-center text-[10px] font-bold">
                {state.currentUser.username.charAt(0)}
             </div>
             {isSidebarOpen && (
               <div className="min-w-0">
                  <p className="text-[10px] font-bold truncate">{state.currentUser.username}</p>
                  <p className="text-[8px] text-slate-500 uppercase">{state.currentUser.role}</p>
               </div>
             )}
          </div>
          <button onClick={() => setState(prev => ({ ...prev, currentUser: null }))} 
            className="w-full p-3 rounded-xl text-red-400 bg-red-500/5 hover:bg-red-500/10 border border-red-500/20 transition-all flex items-center justify-center gap-3">
            <LogOut size={18} /> {isSidebarOpen && <span className="text-sm font-semibold">خروج</span>}
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col min-w-0 relative">
        <header className="h-20 bg-[#0f172a]/80 backdrop-blur-md border-b border-white/5 px-8 flex items-center justify-between z-40">
          <div className="flex items-center gap-6">
             <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="p-2.5 bg-white/5 rounded-xl hover:bg-orange-500 transition-all">
                <Menu size={20} />
             </button>
             <h1 className="text-xl font-bold tracking-tight">{navItems.find(n => n.id === activeTab)?.label}</h1>
          </div>

          <div className="flex items-center gap-4">
             <div className={`flex items-center gap-2 px-4 py-2 rounded-full border border-white/5 text-[10px] font-bold ${syncStatus === 'synced' ? 'text-emerald-500' : 'text-orange-500'}`}>
                {syncStatus === 'syncing' ? <RefreshCw size={12} className="animate-spin"/> : <div className={`w-2 h-2 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-500' : 'bg-red-500'}`}></div>}
                {syncStatus === 'synced' ? 'Eagle OS: Connected' : 'Eagle OS: Syncing...'}
             </div>
             <button onClick={() => window.print()} 
                className="bg-white text-slate-900 px-6 py-2.5 rounded-xl font-bold text-xs hover:bg-orange-500 hover:text-white transition-all shadow-xl flex items-center gap-2">
                <Printer size={16} /> طباعة
             </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
          <div id="report-section" className="max-w-6xl mx-auto space-y-8">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={updateState as any} onMatchClick={(id) => { setSelectedMatchId(id); setActiveTab('matches'); }} onSessionClick={() => setActiveTab('attendance')} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={updateState} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addNotify} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={updateState as any} addLog={addNotify} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={updateState as any} addLog={addNotify} />}
            {activeTab === 'tactics' && <TacticalBoard state={state} setState={updateState} />}
            {activeTab === 'medical' && <MedicalCenter state={state} setState={updateState} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={updateState as any} defaultSelectedId={selectedMatchId} getSuspension={getPlayerSuspension} addLog={addNotify} />}
            {activeTab === 'logistics' && <LocationAssistant />}
            {activeTab === 'warehouse' && <WarehouseManagement state={state} setState={updateState} addLog={addNotify} />}
            {activeTab === 'qr' && <QRManager state={state} setState={updateState} />}
            {activeTab === 'analytics' && <VisualAnalytics state={state} />}
            {activeTab === 'settings' && <SettingsView state={state} setState={updateState as any} addLog={addNotify} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} setState={updateState} onBack={() => setActiveTab('squad')} />}
          </div>
        </div>

        <div className="fixed bottom-8 left-8 z-[999] space-y-2">
          {notifications.map(n => (
            <div key={n.id} className={`p-4 rounded-xl shadow-2xl border-r-4 min-w-[200px] flex items-center gap-3 bg-[#1e293b] text-white animate-in slide-in-from-left-full ${n.type === 'success' ? 'border-emerald-500' : n.type === 'error' ? 'border-red-500' : 'border-blue-500'}`}>
              {n.type === 'success' ? <CheckCircle2 className="text-emerald-500" /> : <AlertCircle className="text-red-500" />}
              <span className="text-xs font-bold">{n.message}</span>
            </div>
          ))}
        </div>
      </div>
      <ChatBot state={state} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Lock, User, Eye, EyeOff, ChevronLeft, Loader2, Sparkles, CheckCircle2 } from 'lucide-react';
import { AppUser } from '../types';
import ClubLogo from './ClubLogo';

interface LoginProps {
  onLoginAttempt: (username: string, password: string) => Promise<AppUser | null>;
}

const Login: React.FC<LoginProps> = ({ onLoginAttempt }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [loginSuccess, setLoginSuccess] = useState(false);

  const techPattern = {
    backgroundImage: `
      radial-gradient(circle at 2px 2px, rgba(255,255,255,0.05) 1px, transparent 0),
      linear-gradient(to right, rgba(255,255,255,0.02) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(255,255,255,0.02) 1px, transparent 1px)
    `,
    backgroundSize: '24px 24px, 40px 40px, 40px 40px'
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!username.trim() || !password) {
      setError('يرجى إدخال اسم المستخدم وكلمة المرور.');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const user = await onLoginAttempt(username, password);
      if (user) {
        setLoginSuccess(true);
      }
    } catch (err: any) {
      setError(err.message || 'فشل تسجيل الدخول. يرجى المحاولة لاحقاً.');
      setLoading(false);
    }
  };

  if (loginSuccess) {
    return (
      <div className="min-h-screen bg-[#001F3F] flex flex-col items-center justify-center p-6 font-['Tajawal'] relative overflow-hidden" dir="rtl" style={techPattern}>
        <div className="relative z-10 flex flex-col items-center animate-in zoom-in duration-700">
          <div className="relative">
             <div className="absolute inset-0 bg-orange-500 rounded-full blur-3xl opacity-20 animate-pulse"></div>
             <div className="bg-white p-10 rounded-full shadow-[0_0_100px_rgba(255,107,0,0.4)] border-8 border-orange-500/20 animate-bounce">
                <ClubLogo size={180} />
             </div>
             <div className="absolute -top-4 -right-4 bg-emerald-500 text-white p-4 rounded-full shadow-2xl animate-in slide-in-from-bottom-4 duration-500">
                <CheckCircle2 size={48} />
             </div>
          </div>
          <h2 className="text-white text-5xl font-black mt-12 tracking-tighter animate-in fade-in slide-in-from-bottom-8 duration-1000">Eagle OS: Authorized</h2>
          <p className="text-orange-400 text-xl font-bold mt-4 opacity-80 uppercase tracking-widest animate-pulse">جاري تحميل بروتوكولات الإدارة الذكية...</p>
          <div className="mt-12 flex gap-2">
             <div className="w-3 h-3 bg-white rounded-full animate-bounce [animation-delay:-0.3s]"></div>
             <div className="w-3 h-3 bg-white rounded-full animate-bounce [animation-delay:-0.15s]"></div>
             <div className="w-3 h-3 bg-white rounded-full animate-bounce"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#001F3F] flex flex-col items-center justify-center p-6 font-['Tajawal'] relative overflow-hidden" dir="rtl" style={techPattern}>
      <div className="absolute top-[-15%] right-[-10%] w-[50%] h-[50%] bg-orange-600/10 rounded-full blur-[120px]"></div>
      <div className="absolute bottom-[-15%] left-[-10%] w-[40%] h-[40%] bg-blue-600/10 rounded-full blur-[100px]"></div>

      <div className="max-w-md w-full bg-white rounded-[4rem] shadow-[0_32px_64px_-12px_rgba(0,0,0,0.5)] overflow-hidden border border-white/20 animate-in fade-in zoom-in-95 duration-700 relative z-10">
        <div className="bg-gradient-to-br from-[#001F3F] to-[#000F21] p-12 flex flex-col items-center text-center">
          <div className="bg-white p-6 rounded-[3rem] shadow-2xl mb-8 ring-8 ring-orange-500/10 transition-transform hover:scale-105 duration-500">
            <ClubLogo size={120} />
          </div>
          <h2 className="text-white font-black text-4xl tracking-tight leading-snug uppercase bg-gradient-to-r from-orange-400 to-white bg-clip-text text-transparent">Eagle OS</h2>
          <p className="text-white font-black mt-2 text-xs uppercase tracking-[0.4em] opacity-60">Football Management Intelligence</p>
          <p className="text-orange-400 font-black mt-5 text-sm uppercase tracking-widest bg-orange-500/10 px-6 py-2 rounded-full border border-orange-500/20">مكتب كرة القدم - نادي الكرامة</p>
        </div>

        <div className="p-12 space-y-8">
          <form onSubmit={handleLogin} className="space-y-8">
            {error && (
              <div className="bg-red-50 text-red-600 p-4 rounded-2xl text-[12px] font-black text-center border-2 border-red-200 animate-bounce">
                {error}
              </div>
            )}

            <div className="space-y-3">
              <label className="text-[11px] font-black text-slate-500 mr-2 uppercase flex items-center gap-2">
                <User size={14} className="text-[#001F3F]" /> المعرف الرقمي
              </label>
              <input 
                type="text" 
                value={username} 
                onChange={e => setUsername(e.target.value)}
                disabled={loading}
                placeholder="Username" 
                className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl py-5 px-8 outline-none focus:ring-4 focus:ring-orange-500/10 focus:border-orange-500 font-black text-slate-800 transition-all text-xl disabled:opacity-50" 
              />
            </div>

            <div className="space-y-3">
              <label className="text-[11px] font-black text-slate-500 mr-2 uppercase flex items-center gap-2">
                <Lock size={14} className="text-[#001F3F]" /> رمز الوصول
              </label>
              <div className="relative">
                <input 
                  type={showPass ? "text" : "password"} 
                  value={password} 
                  onChange={e => setPassword(e.target.value)}
                  disabled={loading}
                  placeholder="Password"
                  className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl py-5 pr-8 pl-16 outline-none focus:ring-4 focus:ring-orange-500/10 focus:border-orange-500 font-black text-slate-800 transition-all text-xl disabled:opacity-50" 
                />
                <button 
                  type="button" 
                  onClick={() => setShowPass(!showPass)} 
                  className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-orange-600 transition-colors p-3"
                >
                  {showPass ? <EyeOff size={24} /> : <Eye size={24} />}
                </button>
              </div>
            </div>

            <button 
              type="submit" 
              disabled={loading}
              className="w-full bg-[#001F3F] text-white font-black py-6 rounded-[2.5rem] hover:bg-black transition-all shadow-2xl shadow-blue-900/40 mt-4 text-2xl flex items-center justify-center gap-4 group disabled:opacity-70 overflow-hidden relative"
            >
              {loading ? (
                <>
                  <Loader2 className="animate-spin" size={28} />
                  Eagle OS: Authenticating...
                </>
              ) : (
                <>
                  تفعيل الدخول الذكي
                  <ChevronLeft className="group-hover:-translate-x-2 transition-transform" size={28} />
                </>
              )}
            </button>
          </form>

          <div className="pt-8 border-t border-slate-100 text-center space-y-2">
            <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em]">Eagle Operating System v3.1</p>
            <p className="text-[10px] text-slate-400 font-bold">AL-KARAMAH SC | Official Management Unit</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Sparkles, Send, Bot, User, Loader2, BrainCircuit, Zap, X, Globe, ExternalLink, BarChart, TrendingUp, ShieldAlert, HeartPulse, History, Gavel, Filter, Trophy, Star, AlertCircle } from 'lucide-react';
import { AppState } from '../types';

interface AIAssistantProps {
  state: AppState;
}

const AIAssistant: React.FC<AIAssistantProps> = ({ state }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [aiMode, setAiMode] = useState<'fast' | 'deep' | 'tactical'>('fast');
  const [selectedCategory, setSelectedCategory] = useState<string>(state.currentUser?.restrictedCategory || state.globalCategoryFilter || 'الكل');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const currentUser = state.currentUser;
  const isManager = currentUser?.role === 'مدير';
  const restrictedCat = currentUser?.restrictedCategory;

  useEffect(() => {
    if (restrictedCat) {
      setSelectedCategory(restrictedCat);
    }
  }, [restrictedCat]);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const clubAnalysis = useMemo(() => {
    const categoryPlayers = state.people.filter(p => 
      p.role === 'لاعب' && (selectedCategory === 'الكل' ? true : p.category === selectedCategory)
    );

    const categoryMatches = state.matches.filter(m => 
      m.isCompleted && (selectedCategory === 'الكل' ? true : m.category === selectedCategory)
    );

    const categorySessions = state.sessions.filter(s => 
      (selectedCategory === 'الكل' ? true : s.category === selectedCategory)
    );

    const medicalHistory = categoryPlayers
      .filter(p => p.injuries || p.medicalHistory)
      .map(p => `- ${p.name}: إصابات (${p.injuries || 'لا يوجد'}), ملاحظات (${p.medicalHistory || 'سليم'})`)
      .join('\n');

    const performanceAndDiscipline = categoryPlayers.map(p => {
      const records = state.attendance.filter(a => a.personId === p.id);
      const lates = records.filter(r => r.status === 'متأخر').length;

      let goals = 0;
      let assists = 0;
      let yellows = 0;
      let reds = 0;

      categoryMatches.forEach(m => {
        goals += m.events.filter(e => e.type === 'goal' && (e.player === p.id || e.player === p.name)).length;
        assists += m.events.filter(e => e.type === 'assist' && (e.player === p.id || e.player === p.name)).length;
        yellows += m.events.filter(e => e.type === 'yellow' && (e.player === p.id || e.player === p.name)).length;
        reds += m.events.filter(e => e.type === 'red' && (e.player === p.id || e.player === p.name)).length;
      });

      const attRate = categorySessions.length > 0 ? Math.round(((records.filter(r => r.status === 'حاضر').length + lates * 0.7) / categorySessions.length) * 100) : 0;

      return `- ${p.name}: أهداف(${goals}), أسيست(${assists}), كروت(🟨:${yellows}, 🟥:${reds}), التزام(${attRate}%)`;
