                 </div>

                 <div className="space-y-4">
                    {sortedSavedReports.length > 0 ? sortedSavedReports.map((report, idx) => (
                      <div key={idx} className="bg-white/5 border-r-4 border-blue-600 p-6 rounded-2xl relative group hover:bg-white/10 transition-all">
                         <div className="flex justify-between items-start mb-3">
                            <span className="bg-blue-600 text-white px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest">{report.month}</span>
                            <BookOpen size={14} className="text-slate-600 group-hover:text-blue-600 transition-colors" />
                         </div>
                         <p className="text-xs font-medium text-slate-300 leading-relaxed whitespace-pre-wrap italic">
                            "{report.content}"
                         </p>
                      </div>
                    )) : (
                      <div className="py-10 text-center border-2 border-dashed border-white/5 rounded-3xl">
                         <AlertCircle className="mx-auto text-slate-700 mb-2" size={32} />
                         <p className="text-[10px] font-black text-slate-600 uppercase">لا توجد تقارير مؤرشفة لهذا اللاعب حالياً</p>
                      </div>
                    )}
                 </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

