  const labelClass = "text-[10px] font-black text-slate-400 uppercase mb-1.5 block flex items-center gap-2 tracking-widest";
  const sectionHeader = "text-orange-500 font-black text-[11px] uppercase tracking-[0.2em] border-r-4 border-orange-500 pr-3 mb-6 mt-8 flex items-center gap-2 bg-orange-500/5 py-2 rounded-l-lg";

