              className="w-full bg-[#0f172a] border border-white/5 rounded-2xl py-4 pr-12 pl-6 text-white outline-none focus:border-orange-500 transition-all font-bold" />
         </div>

         {!restrictedCat ? (
           <div className="relative w-full md:w-64">
             <Filter className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
