               value={localCategoryFilter} 
               onChange={e => setLocalCategoryFilter(e.target.value)}
               className="w-full bg-[#0f172a] border border-white/5 rounded-2xl py-4 pr-12 pl-6 text-white outline-none focus:border-orange-500 transition-all font-black text-xs cursor-pointer appearance-none"
             >
                <option value="الكل">جميع الفئات</option>
                {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
             </select>
           </div>
         ) : (
           <div className="bg-orange-500/10 border border-orange-500/20 px-6 py-4 rounded-2xl text-orange-500 font-black text-xs uppercase tracking-widest">
              فئة: {restrictedCat}
           </div>
         )}

         {!isViewer && (
           <button onClick={() => { setEditingId(null); setFormData(initialFormState); setIsModalOpen(true); }}
             className="bg-orange-500 text-white px-8 py-4 rounded-2xl font-black flex items-center gap-3 shadow-lg hover:bg-orange-600 transition-all whitespace-nowrap w-full md:w-auto justify-center">
              <UserPlus size={20}/> إضافة جديد
           </button>
         )}
      </div>

      {/* تبديل العرض بين اللاعبين والكوادر */}
      <div className="flex p-1.5 bg-[#0f172a] border border-white/5 rounded-2xl w-fit">
          <button onClick={() => setActiveSubTab('players')} className={`px-10 py-3 rounded-xl font-black text-xs transition-all ${activeSubTab === 'players' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>اللاعبين ({state.people.filter(p => p.role==='لاعب' && (!restrictedCat || p.category===restrictedCat)).length})</button>
          <button onClick={() => setActiveSubTab('staff')} className={`px-10 py-3 rounded-xl font-black text-xs transition-all ${activeSubTab === 'staff' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>الكوادر ({state.people.filter(p => p.role!=='لاعب' && (!restrictedCat || p.category===restrictedCat)).length})</button>
      </div>

      {/* قائمة البطاقات */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {filteredMembers.map(person => (
