                <div className="w-16 h-16 bg-slate-800 rounded-2xl flex items-center justify-center font-black text-3xl text-white border-2 border-orange-500/20 shadow-xl group-hover:bg-orange-500 transition-colors">
                   {person.name.charAt(0)}
