                </div>
             </div>
             <h3 className="text-xl font-black text-white mb-2">{person.name} {person.number && <span className="text-orange-500 text-sm">#{person.number}</span>}</h3>
             <p className="text-[10px] text-slate-500 font-bold mb-6">{person.position || 'بدون مركز محدد'}</p>
             <div className="mt-auto pt-6 border-t border-white/5 flex justify-between items-center">
                <button onClick={() => onOpenReport?.(person)} className="text-xs font-black text-slate-400 hover:text-orange-500 flex items-center gap-1 transition-colors">الملف الفني <ChevronRight size={14}/></button>
                <div className="flex gap-2">
                   {!isViewer && (
