           { label: 'الانتصارات', value: analytics.wins, color: 'text-emerald-500', bg: 'bg-emerald-500/10' },
           { label: 'التعادلات', value: analytics.draws, color: 'text-yellow-500', bg: 'bg-yellow-500/10' },
